ANNOTATIONS = [
    (29, 'after', r'''BRIDGE_FAILURE_DISMISS_MS = 10s：失败通知展示 10 秒后自动清掉 replBridgeEnabled，让 hook 停止重试——不自动停的话用户每次重启都在后台撞同一面墙。'''),
    (40, 'after', r'''保险丝：连续 3 次 init 失败后本会话不再尝试。防的是那些会把 replBridgeEnabled 又翻回去的路径（设置同步、/remote-control、config tool）在 OAuth 已不可恢复时每次都白送一次 401。Datadog 2026-03-08：最卡的那个客户端一天打了 2,879 个 401，占该路由全部 401 的 17%。'''),
    (53, 'before', r'''useReplBridge：后台常驻的远程控制桥。把 REPL 的新用户/助手消息写给 claude.ai 会话，把 claude.ai 来的用户消息注入 REPL。桥没开或没 OAuth 就静默跳过；AppState.replBridgeEnabled 是唯一开关（/config 或页脚可切）。'''),
    (62, 'after', r'''flushedUUIDs 跨重连存活：Bridge #2 起只发新消息。重复发同一个 UUID，服务端会直接杀 WebSocket。'''),
    (67, 'after', r'''consecutiveFailures 与 effect 局部状态的区别：它跨 effect 重跑持久，只在 init 成功后清零。到顶即会话级保险丝烧断，replBridgeEnabled 再怎么翻回去都没用。'''),
    (90, 'after', r'''四个 selector 全是 feature('BRIDGE_MODE') 条件调用——编译后只剩一支，非桥构建里这些订阅整条消失。'''),
    (99, 'after', r'''feature() 检查必须写成正向模式：负向的 if (!feature(...)) return 不会消除下面的动态 import（bundler 看不出动态 import 在死分支里），external 构建会把整座 bridge 拖进去。'''),
    (128, 'after', r'''保险丝已烧断：清 replBridgeEnabled（否则 /remote-control 会误显示 BridgeDisconnectDialog——为一个从未连上的桥），带 hint 通知一次，然后本会话不再尝试。'''),
    (132, 'after', r'''此刻抓 messages.length：这些初始消息会作为 initialMessages 进 initReplBridge，转发 effect 要从这个索引之后才开始写，否则同一批消息发两遍。'''),
    (144, 'after', r'''重新初始化前必须等上一个 teardown 走完：上次的 deregister HTTP 和新一次的 register 是竞态，服务端可能把刚创建的新环境连带拆掉。teardownPromiseRef 就是给这里 await 的。'''),
    (150, 'after', r'''动态 import 让 bridge 模块树在非桥构建里被整体摇掉。'''),
    (170, 'after', r'''perpetual（KAIROS assistant 模式）：读 bridge-pointer.json——就是 #20735 为崩溃恢复加的那个文件——复用里面的 {environmentId, sessionId} 走 api.reconnectSession()，claude.ai 上呈现为跨 CLI 重启的一段连续会话。teardown 相应跳过 archive/deregister/清指针，让会话干净退出后也活着；非 assistant 桥拆指针（只保崩溃恢复）。'''),
    (179, 'after_block', r'''handleInboundMessage：claude.ai 来的用户消息进 REPL。两个设计：保留原始 UUID——消息转发回 CCR 时能和原消息对上，不产生重复；异步是因为附件要先网络拉取+落盘，才能带 @path 前缀入队。调用方不 await，带附件的消息晚一点进队无妨（网页消息不是高频流）。'''),
    (200, 'after', r'''webhook 内容消毒只对 KAIROS_GITHUB_WEBHOOKS 构建生效——条件 require 保证这段也不进别的构建。'''),
    (215, 'after', r'''skipSlashCommands + bridgeOrigin 双层防御：processUserInputBase 在 bridgeOrigin 为真且命令通过 isBridgeSafeCommand 时会在内部覆盖 skipSlashCommands；显式传 true 保住那些直接查这个标志的代码路径的退出词抑制和即时命令拦截。'''),
    (248, 'after', r'''outboundOnly 镜像模式只同步 replBridgeConnected 一个标志——转发 effect 靠它起停，传输建立/死亡时跟着翻，不走完整的状态机。'''),
    (272, 'after', r'''ready 状态：组装连接 URL 和会话 URL，六个字段逐个比对，全相同就返回原 state——重连风暴里这个短路省掉大量无意义重渲染。'''),
    (290, 'after_block', r'''system/init 为什么只有这里发：REPL 用 query() 直连主循环，永远不经过 QueryEngine 的 SDKMessage 层，所以这是唯一能把 system/init 放上 REPL-桥线的路径。技能加载是异步的（memoize 过，REPL 启动后很便宜），fire-and-forget 不阻塞状态跳转。GB 开关 tengu_bridge_system_init 控量。'''),
    (306, 'before', r'''三个字段打码不是洁癖是泄漏防护：MCP 前缀工具名和服务器名暴露用户接了哪些集成；插件路径暴露原始文件系统路径（用户名、项目结构）；CCR v2 会把 SDK 消息持久化进 Spanner——点「从手机连接」的用户未必料到这些上了 Anthropic 的服务器。QueryEngine（SDK）仍发全量，SDK 消费者本就期待全量遥测。'''),
    (314, 'after', r'''只广告桥安全命令：把 local-jsx、未授权本地命令广告出去，移动端/网页端会去调然后撞一脸错误。'''),
    (363, 'after', r'''failed：清旧 dismiss 计时器、通知、落错误态，10 秒后自动摘掉 replBridgeEnabled——自动停重试，不等用户干预。'''),
    (386, 'after', r'''control_response 按 request_id 找到挂起的处理器，用完即删——同一个 request 的第二条响应（服务端重发）不会二次触发。'''),
    (405, 'after', r'''onSetModel 的 'default' 是协议里的哨兵值，落到本地就是 null（无覆盖），与 AppState.mainLoopModelForSession 对齐。'''),
    (427, 'before', r'''权限模式设置的 policy guards 必须排在 transitionPermissionMode 之前：后者内部的 auto-gate 检查是带副作用的防御性 throw——setAutoModeActive(true) 先执行再抛。让这个 throw 逃逸的后果：(1) STATE.autoModeActive 停在 true 而模式没变（3-way invariant 违反）；(2) control_response 发不出去，服务端杀 WS。这里的判决与 print.ts 的 handleSetPermissionMode 镜像；bridge 不能直接 import 那些检查（bootstrap 隔离），只能靠返回值拿判决。'''),
    (470, 'after', r'''模式变了要重新评估队列里待决的权限提示（原来按 plan 拦的，现在放行了）。setImmediate 让 setAppState 先落地再扫队列。'''),
    (481, 'after', r'''initReplBridge 的完整回调面：入站消息、权限响应、中断、模型、思考预算、权限模式、状态机；initialMessages 带当前会话上下文，getMessages 供后续增量拉取，previouslyFlushedUUIDs 接住跨重连去重。'''),
    (491, 'after', r'''init 飞行中 effect 被取消（用户又关了桥）：拿到 handle 也要 teardown——否则泄漏轮询、WebSocket、注册的环境和清理回调。'''),
    (517, 'after', r'''返回 null = 前置条件失败（no_oauth、policy_denied 等），onStateChange('failed') 多数已经带着具体 hint 通知过了。GrowthBook 没放量那种情况故意静默——不是失败，只是没 rollout。'''),
    (523, 'after', r'''转发起点设为 initialMessageCount：那批消息在建会话时已经作为 session 事件加载进去了，不能再写一遍。'''),
    (582, 'after', r'''权限回调四件套交给交互式权限处理器，让桥响应和本地用户操作同场竞速（interactiveHandler 的五方竞速里，bridge 就是其中一方）。onResponse 返回注销函数，取消时从 Map 摘掉。'''),
    (613, 'after', r'''env-less v2 路径（environmentId === ''）没有环境专属连接 URL；升级提示只对非 perpetual 弹（perpetual 在 initReplBridge 里回退 v1 了，v2 的 nudge 对它们无意义），且独立 try/catch—— GrowthBook 小颠簸不该进外层 init 失败处理器。'''),
    (648, 'after', r'''catch 里第一件事是检查 cancelled：快速 toggle off 造成的在途网络错误不计入保险丝、不往 UI 里刷一条陈旧错误（对称于 !handle 路径）。'''),
    (678, 'after', r'''cleanup 把 teardownPromise 存下来而不是 await：下次 init 的开头会等它——这就是上面「等上一个 teardown」的存储侧。'''),
    (713, 'after', r'''转发 effect：compaction 之后数组变短，lastWrittenIndex 可能超过 messages.length——不 clamp 的话此后永远没有新消息会被转发。过滤条件只放 user/assistant 和 local_command 系统消息。'''),
    (718, 'after', r'''sendBridgeResult：把「这轮结束了」信号推给远端（远程 UI 靠它收起转圈）。'''),
]
